<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\PlatformIdentity\Infrastructure\Driven;

use Override;
use Throwable;
use Civi\Lughauth\Features\Access\PlatformIdentity\Infrastructure\Connector\Pdo\PlatformIdentityPdoConnector;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityReadGateway;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentitySlide;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityFilter;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityCursor;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\PlatformIdentityRef;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\PlatformIdentity;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class PlatformIdentityReadRepositoryAdapter implements PlatformIdentityReadGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly PlatformIdentityPdoConnector $conn,
    ) {
    }
    #[Override]
    public function resolve(PlatformIdentityRef $ref): ?PlatformIdentity
    {
        if ($ref instanceof PlatformIdentity) {
            return $ref;
        } elseif (!$ref->_private_resolve) {
            $ref->_private_resolve = $this->conn->retrieve(new PlatformIdentityFilter(uids: [ $ref->uid() ]));
        }
        return $ref->_private_resolve;
    }
    #[Override]
    public function list(?PlatformIdentityFilter $filter = null, ?PlatformIdentityCursor $cursor = null): PlatformIdentitySlide
    {
        $this->logDebug("List for Platform identity on adapter ");
        $span = $this->startSpan("List for Platform identity on adapter");
        try {
            $values = $this->conn->list($filter, $cursor);
            $last = end($values);
            return new PlatformIdentitySlide(function (PlatformIdentityFilter $slide, ?PlatformIdentityCursor $next) use ($filter) {
                return $this->list($filter, $next);
            }, new PlatformIdentityCursor($cursor?->limit() ?? 100, false !== $last ? $last->uid() : null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieve(PlatformIdentityFilter $filter): ?PlatformIdentity
    {
        $this->logDebug("Retrieve for Platform identity on adapter ");
        $span = $this->startSpan("Retrieve for Platform identity on adapter");
        try {
            return $this->conn->retrieve($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function exists(PlatformIdentityFilter $filter): bool
    {
        $this->logDebug("Exists for Platform identity on adapter ");
        $span = $this->startSpan("Exists for Platform identity on adapter");
        try {
            return $this->conn->exists($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function count(?PlatformIdentityFilter $filter = null): int
    {
        $this->logDebug("Count for Platform identity on adapter ");
        $span = $this->startSpan("Count for Platform identity on adapter");
        try {
            return $this->conn->count($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneByUid(string $uid): ?PlatformIdentity
    {
        $this->logDebug("Find on by uid for Platform identity on adapter");
        $span = $this->startSpan("Find on by uid for Platform identity on adapter");
        try {
            return $this->conn->retrieve(new PlatformIdentityFilter(uids: [$uid]));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
